def _validate_labels(labels):
    import re
    from collections.abc import Iterable

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        if not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9._-]+$'"})
        elif isinstance(value, Iterable) and not isinstance(value, str):
            for v in value:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
                elif not value_regex.match(v):
                    errors.append({v: f"Label value '{v}' does not match the regex '^[a-zA-Z0-9._-]+$'"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

