def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		# Assuming in-style parameters are either named (e.g., :name) or positional (e.g., %s)
		# and out-style parameters are named (e.g., @name) for named and ? for positional.
		if isinstance(params, dict):
			# Named parameters
			out_params = {f'@{key}': value for key, value in params.items()}
			formatted_sql = sql
			for key in params:
				# Replace :key with @key
				formatted_sql = formatted_sql.replace(f':{key}', f'@{key}')
		else:
			# Positional parameters
			out_params = list(params)
			formatted_sql = sql
			if '%s' in sql:
				# Replace %s with ?
				formatted_sql = sql.replace('%s', '?')
		return formatted_sql, out_params

